// 同栈来源接原Affairs写者；新旧模块严格成对，坏回执按实际发行区间拒绝。
#include "economic_supply_policy_integration.hpp"
#include "world_bundle.hpp"
#include "resident/domains/politics/supply/politics_supply_profile.hpp"
#include "resident/domains/affairs/issued_supply/affairs_issued_supply.hpp"
#include "resident/domains/organization/organization_office_history.hpp"
#include <set>
namespace hanmo::resident {
namespace {
Status enabled(const WorldBundle& w){return w.economic_supply_policies_enabled()&&w.economic_supply_policies_seed_complete&&w.political_supply_adoptions_seed_complete&&w.catalog->economic_supply_policies&&w.catalog->common&&w.catalog->local_economy&&w.catalog->tasks&&w.catalog->affairs&&w.political_takeover_enabled()?common_success():common_failure("EconomicSupplyPolicyProfileRequired");}
// 本tag原已供多个经济命令使用；这里只认具名新发行，不据tag扩大旧回执权限。
Status receipts(const WorldBundle& w){std::set<StableId> seen;for(const auto& row:w.common.state().results.rows()){if(!row.second)continue;const auto& result=*row.second;const auto* effects=result.details?std::get_if<LocalEconomyEffects>(&result.details->data):nullptr;bool source=false;if(effects)for(const auto& id:effects->fact_ids)source|=id.rfind("economic_supply_policy:",0)==0;if(!source&&result.kind!="political_issue_supply_policy")continue;
 if(!w.economic_supply_policies_enabled()||result.kind!="political_issue_supply_policy"||!effects||!effects->receipt_ids.empty()||effects->fact_ids.size()!=1)return common_failure("InvalidEconomicSupplyReceipt",row.first);const auto& id=effects->fact_ids.front();const auto* policy=w.economic_supply_policies.policies.find(id);if(!policy||policy->issued_tick!=result.tick||!seen.insert(id).second)return common_failure("InvalidEconomicSupplyReceipt",row.first);
 const auto split=row.first.rfind(':');if(split==StableId::npos)return common_failure("InvalidEconomicSupplyReceipt",row.first);const auto actor=row.first.substr(0,split);const auto request=organization_instance_sequence(row.first,actor);const auto* last=w.common.state().request_sequences.find(actor);if(!request||!last||*request>*last||actor!=policy->authority.actor_id)return common_failure("InvalidEconomicSupplyReceiptActor",row.first);
 const HistoryRecord* found=nullptr;const HistoryRecord* previous=nullptr;const HistoryRecord* lower_record=nullptr;for(const auto& history:w.common.state().history){if(history.result_id==result.result_id){if(found)return common_failure("InvalidEconomicSupplyReceiptHistory",row.first);found=&history;lower_record=previous;}previous=&history;}
 const auto upper=organization_instance_sequence(result.result_id,"result"),lower=lower_record?organization_instance_sequence(lower_record->result_id,"result"):std::optional<Integer>{0},issued=organization_instance_sequence(id,"economic_supply_policy");if(!found||found->actor_id!=actor||found->tick!=result.tick||found->kind!=result.kind||!upper||!lower||!issued||*issued<=*lower||*issued>=*upper)return common_failure("EconomicSupplyReceiptAllocationMismatch",row.first);
 }return common_success();}
}
EconomicSupplyWorldAccess::EconomicSupplyWorldAccess(const WorldBundle& w,std::unique_ptr<PoliticalTakeoverWorldAccess> takeover,const DynamicStepInput* phase):takeover_(std::move(takeover)),authority_(takeover_->context(),true),adoptions_(takeover_->context()),context_{{w.common,*w.catalog->common,w.local_economy,*w.catalog->local_economy,*w.catalog->economic_supply_policies,w.economic_supply_policies,phase},*w.catalog->tasks,authority_,adoptions_},read_(context_){}
Outcome<std::unique_ptr<EconomicSupplyWorldAccess>> EconomicSupplyWorldAccess::create(const WorldBundle& w,const DynamicStepInput* phase){auto valid=enabled(w);if(!valid.ok)return {false,{},valid.error};auto takeover=PoliticalTakeoverWorldAccess::create(w,*w.catalog->political_takeover,w.political_takeover,phase);if(!takeover.ok)return {false,{},takeover.error};return {true,std::unique_ptr<EconomicSupplyWorldAccess>(new EconomicSupplyWorldAccess(w,std::move(takeover.value),phase)),{}};}
Status validate_economic_supply_world(const WorldBundle& w){const bool active=w.economic_supply_policies_enabled();auto core_layout=validate_economic_supply_layout(active,w.catalog->identity.module_versions);if(!core_layout.ok)return core_layout;auto layout=validate_political_supply_layout(active,w.catalog->identity.module_versions,active?&w.political_supply_adoptions:nullptr,active?std::optional<Integer>{w.economic_supply_policies.version}:std::nullopt);if(!layout.ok)return layout;if(active!=w.economic_supply_policies_seed_complete||active!=w.political_supply_adoptions_seed_complete||active!=bool(w.catalog->economic_supply_policies))return common_failure("EconomicSupplyPolicySeedRequired");
 if(active){auto access=EconomicSupplyWorldAccess::create(w);if(!access.ok)return {false,{},access.error};auto valid=validate_economic_supply_policies(access.value->context());if(!valid.ok)return valid;}else if(!w.economic_supply_policies.policies.empty()||!w.economic_supply_policies.observations.empty()||w.economic_supply_policies.initialized_tick||w.economic_supply_policies.last_observation_tick||!w.political_supply_adoptions.bindings.empty())return common_failure("UnexpectedEconomicSupplyPolicyState");
 for(const auto& row:w.common.state().facts.rows())if(row.second.domain==economic_supply_policy_module&&!active)return common_failure("EconomicSupplyPolicyProfileRequired",row.first);for(const auto& history:w.common.state().history)if(history.kind=="political_issue_supply_policy"&&!active)return common_failure("EconomicSupplyPolicyProfileRequired");return receipts(w);
}
Outcome<EconomicSupplyPolicyQuote> prepare_economic_supply_world(const WorldBundle& w,const StableId& actor,const IssueEconomicSupplyPolicyCommand& command){auto guard=command_common_guard(w,actor,"political_issue_supply_policy");if(!guard.ok)return {false,{},guard.error};auto access=EconomicSupplyWorldAccess::create(w);if(!access.ok)return {false,{},access.error};return preview_economic_supply_policy(access.value->context(),actor,command);}
Outcome<LocalEconomyEffects> commit_economic_supply_world(WorldBundle& w,const StableId& actor,const IssueEconomicSupplyPolicyCommand& command,const EconomicSupplyPolicyQuote& quote){auto guard=command_common_guard(w,actor,"political_issue_supply_policy");if(!guard.ok)return {false,{},guard.error};auto access=EconomicSupplyWorldAccess::create(w);if(!access.ok)return {false,{},access.error};auto issued=issue_economic_supply_policy_in_candidate(w.common,w.economic_supply_policies,access.value->context(),actor,command,quote);if(!issued.ok)return {false,{},issued.error};return {true,{{},{issued.value.policy_fact_id}},{}};}
Outcome<BoundaryValue> query_economic_supply_world(const WorldBundle& w,const LocalEconomyQuery& query){auto access=EconomicSupplyWorldAccess::create(w);if(!access.ok)return {false,{},access.error};OrganizationAccess organizations(w.common,w.organization,*w.catalog->organization,w.local_economy);auto index=build_economic_supply_policy_index(access.value->context(),w.organization,organizations,access.value->responsibilities());if(!index.ok)return {false,{},index.error};auto page=query_economic_supply_policies(access.value->context(),organizations,access.value->responsibilities(),index.value,query);if(!page.ok)return {false,{},page.error};return {true,encode_economic_supply_policy_page(page.value),{}};}
Status project_economic_supply_world_in_candidate(WorldBundle& w,const DynamicStepInput* phase){if(!w.economic_supply_policies_enabled())return common_success();auto access=EconomicSupplyWorldAccess::create(w,phase);if(!access.ok)return {false,{},access.error};return project_affairs_issued_supply_in_candidate(w.common,w.affairs,*w.catalog->affairs,w.tasks,*w.catalog->tasks,access.value->read(),phase);}
Outcome<std::vector<SupplyObservation>> refresh_economic_supply_world(WorldBundle& w){if(!w.economic_supply_policies_enabled())return {true,{}, {}};auto access=EconomicSupplyWorldAccess::create(w);if(!access.ok)return {false,{},access.error};return refresh_economic_supply_observations_in_candidate(w.common,w.economic_supply_policies,access.value->context());}
}
